}
","import React from "react";

// ---------- Radar / spider profile ----------
export function RadarChart({ axes, profiles, size = 240 }:
 { axes: string[]; profiles: { label: string; color: string; values: number[] }[]; size?: number }) {
 const cx = size / 2, cy = size / 2, r = size / 2 - 34, n = axes.length;
 const angle = (i: number) => (Math.PI * 2 * i) / n - Math.PI / 2;
 const pt = (i: number, v: number) => [cx + Math.cos(angle(i)) * r * (v / 100), cy + Math.sin(angle(i)) * r * (v / 100)];
 return (
 <div>
 <svg className="ci-chart" viewBox={`0 0 ${size} ${size}`} style={{ maxWidth: size }}>
 {[0.25, 0.5, 0.75, 1].map(g => (
 <polygon key={g} points={axes.map((_, i) => { const [x, y] = pt(i, g * 100); return `${x},${y}`; }).join(" ")}
 fill="none" stroke="var(--ci-grid-line)" />
 ))}
 {axes.map((a, i) => {
 const [x, y] = pt(i, 100);
 const [lx, ly] = [cx + Math.cos(angle(i)) * (r + 16), cy + Math.sin(angle(i)) * (r + 16)];
 return <g key={a}>
 <line x1={cx} y1={cy} x2={x} y2={y} stroke="var(--ci-grid-line)" />
 <text x={lx} y={ly} textAnchor="middle" dominantBaseline="middle" fontSize="10">{a}</text>
 </g>;
 })}
 {profiles.map(p => {
 const poly = p.values.map((v, i) => { const [x, y] = pt(i, v); return `${x},${y}`; }).join(" ");
 return <g key={p.label}>
 <polygon points={poly} fill={p.color} fillOpacity="0.14" stroke={p.color} strokeWidth="2" />
 {p.values.map((v, i) => { const [x, y] = pt(i, v); return <circle key={i} cx={x} cy={y} r="2.6" fill={p.color} />; })}
 </g>;
 })}
 </svg>
 <div className="ci-legend">
 {profiles.map(p => <span key={p.label} className="ci-legend__item">
 <span className="ci-legend__swatch" style={{ background: p.color }} />{p.label}</span>)}
 </div>
 </div>
 );
}
","import React from "react";

// ---------- Trend curve (multi-series area/line) ----------
export function TrendCurve({ series, height = 200, labels }:
 { series: { name: string; color: string; data: number[] }[]; height?: number; labels?: string[] }) {
 const [off, setOff] = React.useState<Record<string, boolean>>({});
 const w = 560, h = height, pad = 24;
 const all = series.flatMap(s => s.data);
 const max = Math.max(...all) * 1.1, min = Math.min(...all, 0);
 const rng = max - min || 1, n = series[0]?.data.length || 1;
 const X = (i: number) => pad + (i / (n - 1)) * (w - pad * 2);
 const Y = (v: number) => h - pad - ((v - min) / rng) * (h - pad * 2);
 return (
 <div>
 <svg className="ci-chart" viewBox={`0 0 ${w} ${h}`}>
 {[0, 0.25, 0.5, 0.75, 1].map(g => (
 <line key={g} x1={pad} x2={w - pad} y1={pad + g * (h - pad * 2)} y2={pad + g * (h - pad * 2)}
 stroke="var(--ci-grid-line)" />
 ))}
 {labels && labels.map((l, i) => i % 2 === 0 && (
 <text key={i} x={X(i)} y={h - 6} textAnchor="middle">{l}</text>
 ))}
 {series.map(s => {
 if (off[s.name]) return null;
 const line = s.data.map((v, i) => (i ? "L" : "M") + X(i) + " " + Y(v)).join(" ");
 const gid = "tc" + s.name.replace(/\W/g, "");
 return (
 <g key={s.name}>
 <defs><linearGradient id={gid} x1="0" y1="0" x2="0" y2="1">
 <stop offset="0%" stopColor={s.color} stopOpacity="0.28" />
 <stop offset="100%" stopColor={s.color} stopOpacity="0" />
 </linearGradient></defs>
 <path d={`${line} L ${X(n - 1)} ${h - pad} L ${X(0)} ${h - pad} Z`} fill={`url(#${gid})`} />
 <path d={line} fill="none" stroke={s.color} strokeWidth="2.2" strokeLinecap="round" />
 {s.data.map((v, i) => <circle key={i} cx={X(i)} cy={Y(v)} r="2.4" fill={s.color} />)}
 </g>
 );
 })}
 </svg>
 <div className="ci-legend">
 {series.map(s => (
 <span key={s.name} className={`ci-legend__item ${off[s.name] ? "ci-legend__item--off" : ""}`}
 onClick={() => setOff(o => ({ ...o, [s.name]: !o[s.name] }))}>
 <span className="ci-legend__swatch" style={{ background: s.color }} />{s.name}
 </span>
 ))}
 </div>
 </div>
 );
}

// ---------- Talent funnel ----------
const SC: Record<string, string> = { green: "var(--ci-green)", amber: "var(--ci-amber)", red: "var(--ci-red)", cyan: "var(--ci-cyan)" };
export function Funnel({ stages, onSelect }: { stages: { label: string; value: number; status: string }[]; onSelect?: (i: number) => void }) {
 if (!stages || stages.length === 0) return null;
 const max = stages[0].value || 1;
 return (
 <div style={{ display: "flex", flexDirection: "column", gap: 7 }}>
 {stages.map((s, i) => {
 const pct = s.value / max;
 const conv = i ? Math.round((s.value / stages[i - 1].value) * 100) : 100;
 return (
 <div key={s.label} onClick={() => onSelect?.(i)} style={{ cursor: "pointer" }}>
 <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11.5, marginBottom: 3 }}>
 <span className="ci-dim">{s.label}</span>
 <span className="ci-num" style={{ fontWeight: 600 }}>{s.value.toLocaleString()}
 {i > 0 && <span className="ci-faint" style={{ marginLeft: 6 }}>{conv}%</span>}</span>
 </div>
 <div style={{ height: 22, borderRadius: 6, background: "rgba(120,160,220,0.08)", overflow: "hidden" }}>
 <div style={{ width: `${Math.max(pct * 100, 6)}%`, height: "100%", borderRadius: 6,
 background: `linear-gradient(90deg, ${SC[s.status]}, ${SC[s.status]}88)`, transition: "width .6s ease" }} />
 </div>
 </div>
 );
 })}
 </div>
 );
}

// ---------- Benchmark bars (you vs intl) ----------
export function BenchmarkBars({ data }: { data: { label: string; you: number; intl: number }[] }) {
 return (
 <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
 {data.map(d => {
 const lead = d.you >= d.intl;
 return (
 <div key={d.label}>
 <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11.5, marginBottom: 4 }}>
 <span className="ci-dim">{d.label}</span>
 <span style={{ color: lead ? "var(--ci-green)" : "var(--ci-amber)", fontWeight: 600 }}>{d.you}</span>
 </div>
 <div style={{ position: "relative", height: 8, borderRadius: 5, background: "rgba(120,160,220,0.1)" }}>
 <div style={{ position: "absolute", left: 0, top: 0, height: "100%", width: `${d.you}%`, borderRadius: 5,
 background: lead ? "var(--ci-green)" : "var(--ci-amber)" }} />
 <div title="International benchmark" style={{ position: "absolute", left: `${d.intl}%`, top: -3, width: 2, height: 14,
 background: "var(--ci-violet)", boxShadow: "0 0 6px var(--ci-violet)" }} />
 </div>
 </div>
 );
 })}
 <div className="ci-legend"><span className="ci-legend__item"><span className="ci-legend__swatch" style={{ background: "var(--ci-violet)" }} />International benchmark</span></div>
 </div>
 );
}

// ---------- Radial gauge ----------
export function RadialGauge({ value, label, color = "var(--ci-cyan)", size = 120 }:
 { value: number; label: string; color?: string; size?: number }) {
 const r = size / 2 - 10, c = 2 * Math.PI * r, cx = size / 2;
 return (
 <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
 <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
 <circle cx={cx} cy={cx} r={r} fill="none" stroke="rgba(120,160,220,0.12)" strokeWidth="9" />
 <circle cx={cx} cy={cx} r={r} fill="none" stroke={color} strokeWidth="9" strokeLinecap="round"
 strokeDasharray={c} strokeDashoffset={c - (value / 100) * c}
 transform={`rotate(-90 ${cx} ${cx})`} style={{ transition: "stroke-dashoffset .8s ease", filter: `drop-shadow(0 0 6px ${color})` }} />
 <text x={cx} y={cx - 2} textAnchor="middle" fontSize="24" fontWeight="700" fill="var(--ci-text)">{value}</text>
 <text x={cx} y={cx + 16} textAnchor="middle" fontSize="9">/ 100</text>
 </svg>
 <span className="ci-faint" style={{ fontSize: 11 }}>{label}</span>
 </div>
 );
}
