","// National Talent Radar — connected demo data (POV/POC).
// Reuses the 13 KSA regions from command.ts; adds discovery, benchmark, cohort & source data.
import type { Status } from './demo'
import { REGIONS_T, RegionT, NATIONAL_CONVERSION_AVG } from './command'

const sp = (seed: number, n = 18) => {
 let s = seed
 const r = () => (s = (s * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff
 let v = 42 + r() * 16
 const out: number[] = []
 for (let i = 0; i < n; i++) {
 v = Math.max(8, Math.min(96, v + (r() - 0.42) * 14))
 out.push(v)
 }
 return out
}

