 },
]

// ---- Region-derived opportunity metrics ----
const avgDiscovered = REGIONS_T.reduce((s, r) => s + r.discovered, 0) / REGIONS_T.length
export function regionDerived(r: RegionT) {
 const coverage = Math.round((r.assessed / r.discovered) * 100)
 const participationIdx = Math.round((r.discovered / avgDiscovered) * 100)
 const opportunity = Math.max(
 0,
 Math.min(
 100,
 Math.round(
 (participationIdx / 100) * 34 +
 Math.max(0, NATIONAL_CONVERSION_AVG - r.conversion) * 6 +
 Math.max(0, 55 - coverage) * 0.7
 )
 )
 )
 return { coverage, participationIdx, participationVsAvg: participationIdx - 100, opportunity }
}
export function highestOpportunityRegion() {
 return [...REGIONS_T].sort((a, b) => regionDerived(b).opportunity - regionDerived(a).opportunity)[0].key
}

export { REGIONS_T, NATIONAL_CONVERSION_AVG }
